import subprocess

ARCHIVE_DIR = "/var/backups"


def _clean_label(label):
    return label.strip().lower()


def create_archive(label, source_dir):
    target = f"{ARCHIVE_DIR}/{_clean_label(label)}.tar.gz"
    subprocess.run(f"tar -czf {target} {source_dir}", shell=True, check=True)
    return target
